// Package kit is the one place a connector states the facts about its
// operations: name, class, reversibility, summary, usage line, rate, target,
// parameters. The same facts used to be typed by hand in about ten files (the
// adapter map, the `chap` command table and its help, the API manual, the
// OpenAPI params schema that the MCP tool schema is read from, the baseline
// rate); here they are declared once, as plain Go values, and the rest is
// derived from them:
//
//   - the manual entry (api/manual.yaml) and the params schema
//     (api/openapi.yaml) are generated by `go generate ./internal/connectors/...`
//     into marked regions of those files, and a test fails when a region is out
//     of date. See [SyncFile];
//   - the `chap` command of a simple operation is built from the declaration
//     (cmd/chap/kitcmd.go). An operation that needs more sets [CLI.Custom] and
//     keeps a hand-written command;
//   - an adapter is bound to its declaration by [Bind], which refuses to start
//     when an operation has a declaration and no adapter, or the other way
//     round.
//
// What a declaration does NOT carry, on purpose: whether an operation is
// enabled (that is the baseline pack, a reviewed policy change), the conditions
// under which it is allowed, its approval card text, how it is made idempotent,
// and how text from outside is treated. Those stay hand-written in the
// connector, where a reviewer can read them.
//
// A declaration cannot replace an entry that is written by hand: the catalog
// loader refuses a duplicate key, the generator only rewrites its own marked
// regions, and [Connector.Validate] holds every declared operation to the
// loader's own limits. A declaration also cannot make a class looser without
// showing: the generated manual entry is part of the diff, and each connector
// is pinned in the one table of internal/connectors/declared (see [DiffPins]).
//
// This package uses the standard library only. `chap` imports it, and `chap`
// must stay small.
package kit

import (
	"errors"
	"fmt"
	"regexp"
	"slices"
	"strings"
	"unicode"
)

// Class is an operation's class, as in the op catalog and the spec.
type Class string

// The four classes. The authority for what each one means is internal/policy;
// TestKitClassesAgreeWithPolicy in package declared checks that the four values
// here are the four values there.
const (
	Routine  Class = "routine"
	Gated    Class = "gated"
	High     Class = "high"
	Critical Class = "critical"
)

// Valid reports whether c is one of the four classes.
func (c Class) Valid() bool {
	switch c {
	case Routine, Gated, High, Critical:
		return true
	}
	return false
}

// Reversibility says whether an operation can be undone.
type Reversibility string

// The three values of the catalog.
const (
	Reversible   Reversibility = "reversible"
	Compensable  Reversibility = "compensable"
	Irreversible Reversibility = "irreversible"
)

// Valid reports whether r is one of the three values.
func (r Reversibility) Valid() bool {
	return r == Reversible || r == Compensable || r == Irreversible
}

// Kind is the type of one parameter.
type Kind int

// The parameter kinds the generic command line understands.
const (
	// Bool is a flag with no value; it is sent only when set.
	Bool Kind = iota + 1
	// String is a flag with a text value.
	String
	// Text is the parameter `body`, given as --body or --body-file.
	Text
)

// Param is one parameter of an operation.
type Param struct {
	// Name is the key in the request's params.
	Name string
	Kind Kind
	// Required is for String and Text; a Bool flag cannot be required.
	Required bool
	// MinLength and MaxLength bound a String or Text in the params schema
	// (MinLength 0 leaves the minimum out). MaxLength is required for both.
	MinLength, MaxLength int
	// Flag is the command-line flag; it defaults to Name.
	Flag string
	// Placeholder is the value's name in the usage line of a String flag.
	Placeholder string
	// Help is the flag's help text, for a Bool or String. A Text parameter
	// uses the help of the shared --body and --body-file flags.
	Help string
}

// FlagName is the command-line flag of the parameter, without dashes.
func (p Param) FlagName() string {
	if p.Flag != "" {
		return p.Flag
	}
	return p.Name
}

// Target says what the operation acts on: `target.ref` of the request.
type Target struct {
	// Adapter is `target.adapter`: the name of the connector's adapter.
	Adapter string
	// Pattern is an anchored regular expression the ref must match; the
	// command line checks it before it sends anything. The adapter checks the
	// ref again: this is a convenience, not the guard.
	Pattern string
	// Why is the usage error for a ref that does not match Pattern.
	Why string

	// Exactly one of Positional and Flag is set.
	//
	// Positional is the placeholder of a ref given as the one positional
	// argument, for example "SHOP-12" (shown as <SHOP-12>).
	Positional string
	// Flag is the flag that names the ref, with Placeholder for its value,
	// Default for the ref when the flag is left out, and Help for its text.
	Flag, Placeholder, Default, Help string
}

// CLI says how the operation is run from the command line.
type CLI struct {
	// Custom means a hand-written command exists for this operation and the
	// generic one must not be built.
	Custom bool
	// Summary is the line `chap help` shows. It defaults to the catalog
	// summary with the first letter in lower case and no final full stop.
	Summary string
}

// Op is the declaration of one operation.
type Op struct {
	// Name is the op kind: "intake.list".
	Name  string
	Class Class
	// Reversibility is as the catalog states it.
	Reversibility Reversibility
	// Summary and Usage are the catalog's (`chap manual`); at most 60 and 100
	// characters, like the catalog loader requires.
	Summary string
	Usage   string
	// RatePerMinute is the baseline pack's per-caller rate for the op. The
	// baseline stays the authority (and the place an op is enabled); a test
	// fails when the two differ.
	RatePerMinute int
	// Doc is the prose of the params schema in api/openapi.yaml: what the
	// target must be and what the params mean.
	Doc    string
	Target Target
	Params []Param
	CLI    CLI
}

// Connector is the set of operations one connector provides.
type Connector struct {
	// Name is the connector's name: "linear". It names its generated regions.
	Name string
	Ops  []Op
}

// Names returns the op kinds of the connector, in declaration order.
func (c Connector) Names() []string {
	names := make([]string, len(c.Ops))
	for i, o := range c.Ops {
		names[i] = o.Name
	}
	return names
}

// ParamNames returns the keys of the operation's params, in declaration order.
// An adapter passes them to its "refuse any param the op does not define"
// check, so the allowed keys are the declared ones.
func (o Op) ParamNames() []string {
	names := make([]string, len(o.Params))
	for i, p := range o.Params {
		names[i] = p.Name
	}
	return names
}

// ParamsSchemaName is the component of api/openapi.yaml that describes the
// op's params: "intake.list" is "ParamsIntakeList".
func (o Op) ParamsSchemaName() string {
	var b strings.Builder
	b.WriteString("Params")
	for _, part := range strings.Split(o.Name, ".") {
		if part != "" {
			b.WriteString(strings.ToUpper(part[:1]) + part[1:])
		}
	}
	return b.String()
}

var (
	opNameRE    = regexp.MustCompile(`^[a-z][a-z0-9]*(\.[a-z][a-z0-9]*)+$`)
	paramNameRE = regexp.MustCompile(`^[a-z][a-z0-9_]{0,39}$`)
	flagNameRE  = regexp.MustCompile(`^[a-z][a-z0-9-]{0,39}$`)
	adapterRE   = regexp.MustCompile(`^[a-z][a-z0-9-]{0,38}$`)
	connNameRE  = regexp.MustCompile(`^[a-z][a-z0-9-]{0,38}$`)
	flagTokenRE = regexp.MustCompile(`--[a-z][a-z0-9-]*`)
)

// CommonFlags are the flags every op command of chap takes (cmd/chap's
// common.register). A generated command may not reuse one. A test in cmd/chap
// checks that this list is the list chap registers.
var CommonFlags = []string{"json", "project", "reason", "approval", "request", "wait"}

// Limits of the catalog loader (internal/policy), which has the last word.
const (
	maxSummary = 60
	maxUsage   = 100
)

// Validate checks one declaration. It holds an operation to what the catalog
// loader and the generic command line need, and to one rule of its own: an
// operation that cannot be undone is never routine or gated.
func (o Op) Validate() error {
	fail := func(format string, a ...any) error {
		return fmt.Errorf("kit: %s: %s", o.Name, fmt.Sprintf(format, a...))
	}
	if !opNameRE.MatchString(o.Name) {
		return fmt.Errorf("kit: op name %q is not group.verb in lower case", o.Name)
	}
	switch {
	case !o.Class.Valid():
		return fail("class %q is not routine, gated, high or critical", o.Class)
	case !o.Reversibility.Valid():
		return fail("reversibility %q is not reversible, compensable or irreversible", o.Reversibility)
	case o.Reversibility == Irreversible && o.Class != High && o.Class != Critical:
		return fail("an irreversible operation must be class high or critical, not %s", o.Class)
	case o.Summary == "" || len(o.Summary) > maxSummary:
		return fail("summary must be 1-%d characters", maxSummary)
	case o.Usage == "" || len(o.Usage) > maxUsage:
		return fail("usage must be 1-%d characters", maxUsage)
	case o.RatePerMinute < 1:
		return fail("rate_per_minute must be at least 1")
	case strings.TrimSpace(o.Doc) == "":
		return fail("doc is empty: say what the target must be and what the params mean")
	}
	for _, s := range []string{o.Name, o.Summary, o.Usage, o.Doc, o.CLI.Summary} {
		if i := strings.IndexFunc(s, unicode.IsControl); i >= 0 {
			return fail("a text has a control character at byte %d", i)
		}
	}
	// A custom command is written by hand, so its ref may be computed (read
	// from git, for instance) and its flags are its own. What the catalog and
	// the params schema need is still checked: the adapter name, and each
	// param's name, kind and bounds.
	if err := o.Target.validate(o.CLI.Custom); err != nil {
		return fail("%v", err)
	}
	seen := map[string]bool{}
	flags := map[string]bool{"help": true, "h": true}
	for _, f := range CommonFlags {
		flags[f] = true
	}
	if o.Target.Flag != "" {
		flags[o.Target.Flag] = true
	}
	for _, p := range o.Params {
		if err := p.validate(o.CLI.Custom); err != nil {
			return fail("param %q: %v", p.Name, err)
		}
		if seen[p.Name] {
			return fail("param %q is declared twice", p.Name)
		}
		seen[p.Name] = true
		if o.CLI.Custom {
			continue
		}
		names := []string{p.FlagName()}
		if p.Kind == Text {
			names = []string{"body", "body-file"}
		}
		for _, f := range names {
			if flags[f] {
				return fail("flag --%s is used twice (the common flags are --%s)", f, strings.Join(CommonFlags, " --"))
			}
			flags[f] = true
		}
	}
	if !o.CLI.Custom {
		if o.CLI.Summary != "" && (strings.HasSuffix(o.CLI.Summary, ".") || len(o.CLI.Summary) > 80) {
			return fail("cli summary must be at most 80 characters with no final full stop")
		}
		// The catalog usage is hand-written, because it shows the agent's
		// normal call and not every flag. It may not name a flag that does not
		// exist.
		want := "chap " + o.CLIPath()
		if o.Usage != want && !strings.HasPrefix(o.Usage, want+" ") {
			return fail("usage must start with %q", want)
		}
		for _, f := range flagTokenRE.FindAllString(o.Usage, -1) {
			if !flags[strings.TrimPrefix(f, "--")] {
				return fail("usage names %s, which the command does not take", f)
			}
		}
	}
	return nil
}

func (t Target) validate(custom bool) error {
	if !adapterRE.MatchString(t.Adapter) {
		return fmt.Errorf("target adapter %q is not a short lower-case name", t.Adapter)
	}
	if custom {
		return nil
	}
	switch {
	case (t.Positional == "") == (t.Flag == ""):
		return errors.New("target needs exactly one of Positional and Flag")
	case t.Why == "":
		return errors.New("target needs Why, the usage error for a bad ref")
	}
	if _, err := regexp.Compile(t.Pattern); err != nil || !strings.HasPrefix(t.Pattern, "^") || !strings.HasSuffix(t.Pattern, "$") {
		return fmt.Errorf("target pattern %q must be an anchored regular expression (^...$)", t.Pattern)
	}
	if t.Flag != "" {
		if !flagNameRE.MatchString(t.Flag) || t.Placeholder == "" || t.Default == "" || t.Help == "" {
			return errors.New("a target flag needs a flag name, Placeholder, Default and Help")
		}
	} else if t.Placeholder != "" || t.Default != "" || t.Help != "" {
		return errors.New("a positional target takes no Placeholder, Default or Help")
	}
	return nil
}

// validate checks a param. The name, the kind and the bounds go into the
// params schema, so they are checked for every op. The flag rules are for the
// generated command only: a custom command has its own flags.
func (p Param) validate(custom bool) error {
	if !paramNameRE.MatchString(p.Name) {
		return errors.New("name must be lower case letters, digits and _")
	}
	switch p.Kind {
	case Bool, String, Text:
	default:
		return errors.New("unknown kind")
	}
	if !custom {
		if p.Flag != "" && !flagNameRE.MatchString(p.Flag) {
			return errors.New("flag must be lower case letters, digits and -")
		}
		switch p.Kind {
		case Bool:
			if p.Required {
				return errors.New("a bool flag cannot be required")
			}
			if p.Help == "" {
				return errors.New("a bool flag needs Help")
			}
		case String:
			if p.Placeholder == "" || p.Help == "" {
				return errors.New("a string flag needs Placeholder and Help")
			}
		case Text:
			if p.Name != "body" {
				return errors.New("a text param is named body (--body, --body-file); write a custom command for another name")
			}
		}
	}
	if p.Kind != Bool && (p.MaxLength < 1 || p.MinLength < 0 || p.MinLength > p.MaxLength) {
		return errors.New("MaxLength must be set, and MinLength must not exceed it")
	}
	if p.Kind == Bool && (p.MinLength != 0 || p.MaxLength != 0) {
		return errors.New("a bool has no length")
	}
	return nil
}

// Validate checks every operation, and that no name is declared twice.
func (c Connector) Validate() error {
	if !connNameRE.MatchString(c.Name) {
		return fmt.Errorf("kit: connector name %q is not a short lower-case name", c.Name)
	}
	if len(c.Ops) == 0 {
		return fmt.Errorf("kit: connector %s declares no operations", c.Name)
	}
	seen := map[string]bool{}
	for _, o := range c.Ops {
		if err := o.Validate(); err != nil {
			return err
		}
		if seen[o.Name] {
			return fmt.Errorf("kit: %s is declared twice in connector %s", o.Name, c.Name)
		}
		seen[o.Name] = true
		if o.Target.Adapter != c.Ops[0].Target.Adapter {
			return fmt.Errorf("kit: %s names adapter %q, the other operations of %s name %q", o.Name, o.Target.Adapter, c.Name, c.Ops[0].Target.Adapter)
		}
	}
	return nil
}

// Bind pairs a connector's adapters with its declarations. It is the start-up
// check that a declared operation has an adapter and that an adapter has a
// declaration, so no operation can run without its catalog entry or appear in
// the catalog without code behind it. The returned map is a copy.
func Bind[A any](c Connector, impls map[string]A) (map[string]A, error) {
	if err := c.Validate(); err != nil {
		return nil, err
	}
	out := make(map[string]A, len(impls))
	for _, o := range c.Ops {
		a, ok := impls[o.Name]
		if !ok {
			return nil, fmt.Errorf("kit: %s is declared by connector %s and has no adapter", o.Name, c.Name)
		}
		out[o.Name] = a
	}
	for name := range impls {
		if !slices.Contains(c.Names(), name) {
			return nil, fmt.Errorf("kit: connector %s has an adapter for %s and no declaration", c.Name, name)
		}
	}
	return out, nil
}

// Pin is the class and reversibility a connector's test says an operation has,
// written out independently of the declaration.
type Pin struct {
	Class         Class
	Reversibility Reversibility
}

// DiffPins compares a connector's declarations with a table written by hand
// in the connector's test. It reports an operation that has no pin, a pin with
// no operation, and a value that differs. The table is the tripwire for a
// change of class: loosening one means editing the declaration, the generated
// manual entry and this table, all three in one reviewed change.
func DiffPins(c Connector, pins map[string]Pin) []string {
	var out []string
	for _, o := range c.Ops {
		p, ok := pins[o.Name]
		switch {
		case !ok:
			out = append(out, fmt.Sprintf("%s has no pin: add its class and reversibility to the test's table", o.Name))
		case p.Class != o.Class:
			out = append(out, fmt.Sprintf("%s: class is %s, the pin says %s", o.Name, o.Class, p.Class))
		case p.Reversibility != o.Reversibility:
			out = append(out, fmt.Sprintf("%s: reversibility is %s, the pin says %s", o.Name, o.Reversibility, p.Reversibility))
		}
	}
	for name := range pins {
		if !slices.Contains(c.Names(), name) {
			out = append(out, fmt.Sprintf("the table pins %s, which the connector does not declare", name))
		}
	}
	slices.Sort(out)
	return out
}
